Voici un programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string wordToCount; // mot à compter
    int count = 0; // nombre d'occurrences

    // demander l'entrée du mot à compter
    cout << "Entrez le mot à compter : ";
    cin >> wordToCount;

    // ouvrir le fichier texte
    ifstream inputFile;
    inputFile.open("text_file.txt");

    if (!inputFile) {
        cerr << "Erreur : Impossible d'ouvrir le fichier." << endl;
        return 1;
    }

    // lire le fichier ligne par ligne
    string line;
    while (getline(inputFile, line)) {
        // convertir la ligne en petit lettres pour la comparaison
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // compter le nombre d'occurrences du mot dans la ligne
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != string::npos) {
            count++;
            pos += wordToCount.length();
        }
    }

    // fermer le fichier
    inputFile.close();

    // afficher le nombre d'occurrences du mot dans le fichier
    cout << "Le mot '" << wordToCount << "' apparaît " << count << " fois dans le fichier." << endl;

    return 0;
}
